namespace Inventory;

/// <summary>
/// Provides the inventory API while delegating each responsibility to a focused component.
/// </summary>
public sealed class StockController
{
    private readonly StockAdjustmentService _adjustments = new();
    private readonly ReorderPolicy _reorder = new();
    private readonly ZoneAllocator _zones = new();
    private readonly SupplierOrderingService _ordering;
    private readonly StockAnalysisService _analysis;

    public StockController(ISupplier supplier)
    {
        _ordering = new SupplierOrderingService(supplier, _reorder);
        _analysis = new StockAnalysisService(_reorder, _zones);
    }

    public int AdjustStock(StockItem item, int delta) =>
        _adjustments.AdjustStock(item, delta);

    public int Available(StockItem item) =>
        _adjustments.Available(item);

    public int MovementCount => _adjustments.MovementCount;

    public bool NeedsReorder(StockItem item) =>
        _reorder.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) =>
        _reorder.ReorderQuantity(item);

    public int ResolveThreshold(string sku) =>
        _reorder.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _zones.AllocateToZone(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) =>
        _zones.ZoneSpare(warehouse);

    public bool PlaceReorder(StockItem item) =>
        _ordering.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _ordering.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) =>
        _analysis.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _analysis.AuditStock(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _analysis.ForecastDepletion(item, dailyDemand);
}

internal sealed class StockAdjustmentService
{
    private readonly List<string> _movements = new();

    public int MovementCount => _movements.Count;

    public int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;

        item.OnHand += delta;
        _movements.Add(delta > 0
            ? $"IN {item.Sku} {delta}"
            : $"OUT {item.Sku} {-delta}");

        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");

        return item.OnHand;
    }

    public int Available(StockItem item) =>
        Math.Max(0, item.OnHand - item.Reserved);
}

internal sealed class ReorderPolicy
{
    private const int DefaultReorder = 20;
    private readonly Dictionary<string, int> _reorderThresholds =
        new(StringComparer.Ordinal);

    public bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;

        int threshold = item.ReorderPoint > 0
            ? item.ReorderPoint
            : ResolveThreshold(item.Sku);
        return Available(item) <= threshold;
    }

    public int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;

        int target = item.ReorderPoint > 0
            ? item.ReorderPoint * 2
            : DefaultReorder * 2;
        int quantity = target - Available(item);

        if (quantity < 0)
            return 0;
        return Math.Max(5, quantity);
    }

    public int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return DefaultReorder;
        return _reorderThresholds.TryGetValue(sku, out int threshold)
            ? threshold
            : DefaultReorder;
    }

    private static int Available(StockItem item) =>
        item.OnHand - item.Reserved;
}

internal sealed class ZoneAllocator
{
    private readonly Dictionary<string, int> _zoneUsage =
        new(StringComparer.Ordinal);

    public string AllocateToZone(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";

        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";

        foreach (var zone in warehouse.Zones)
        {
            int used = UsageFor(zone.Name);
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;

            int placed = Math.Min(need, spare);
            _zoneUsage[zone.Name] = used + placed;
            need -= placed;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }

        return "overflow";
    }

    public int ZoneSpare(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            int available = zone.Capacity - UsageFor(zone.Name);
            if (available > 0)
                spare += available;
        }
        return spare;
    }

    public int UsageFor(string zoneName) =>
        _zoneUsage.TryGetValue(zoneName, out int usage) ? usage : 0;
}

internal sealed class SupplierOrderingService
{
    private readonly ISupplier _supplier;
    private readonly ReorderPolicy _reorder;
    private readonly Dictionary<string, int> _pending =
        new(StringComparer.Ordinal);

    public SupplierOrderingService(ISupplier supplier, ReorderPolicy reorder)
    {
        _supplier = supplier;
        _reorder = reorder;
    }

    public bool PlaceReorder(StockItem item)
    {
        int quantity = _reorder.ReorderQuantity(item);
        if (quantity <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out int existing) && existing >= quantity)
            return false;

        bool accepted = _supplier.PlaceOrder(item.Sku, quantity);
        if (accepted)
            _pending[item.Sku] = quantity;
        return accepted;
    }

    public bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0 || !_pending.TryGetValue(item.Sku, out int quantity))
            return false;

        item.OnHand += delivered;
        if (delivered >= quantity)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = quantity - delivered;
        return true;
    }
}

internal sealed class StockAnalysisService
{
    private readonly ReorderPolicy _reorder;
    private readonly ZoneAllocator _zones;

    public StockAnalysisService(ReorderPolicy reorder, ZoneAllocator zones)
    {
        _reorder = reorder;
        _zones = zones;
    }

    public string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        AddItemFindings(item, findings);
        AddZoneFindings(warehouse, findings);

        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    public int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;

        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;

        int days = available / dailyDemand;
        if (days > 365)
            return 365;
        if (_reorder.ResolveThreshold(item.Sku) > 0 &&
            available <= _reorder.ResolveThreshold(item.Sku))
            return 1;
        return days;
    }

    private static void AddItemFindings(StockItem item, ICollection<string> findings)
    {
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");
    }

    private void AddZoneFindings(Warehouse warehouse, ICollection<string> findings)
    {
        foreach (var zone in warehouse.Zones)
        {
            int used = _zones.UsageFor(zone.Name);
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }
    }
}
